// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address ownerCandidate, address newOwner) public {
        vm.assume(ownerCandidate != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(ownerCandidate != newOwner);

        vm.prank(address(0));
        c.transferOwnership(ownerCandidate);

        vm.prank(ownerCandidate);
        c.transferOwnership(newOwner);

        assertEq(c.owner(), newOwner, "Owner should be updated to newOwner");
    }
}
